@@ -5,18 +5,30 @@ import (
 type Cache struct {
 	mu    sync.RWMutex
 	items map[string]item
+	// 默认过期时间，0 表示永不过期
+	moRenGuoQi time.Duration
 }

+type item struct {
+	value    any
+	guoQiShi time.Time // 过期时间点
+}
+
 func (c *Cache) Get(key string) (any, bool) {
 	c.mu.RLock()
-	defer c.mu.RUnlock()
 	it, ok := c.items[key]
-	return it.value, ok
+	c.mu.RUnlock()
+	if !ok {
+		return nil, false
+	}
+	// 已过期的条目顺手删掉，避免内存一直涨
+	if !it.guoQiShi.IsZero() && time.Now().After(it.guoQiShi) {
+		delete(c.items, key)
+		return nil, false
+	}
+	return it.value, true
 }
